#!/usr/bin/env python3
"""
Correcao tripla (roda a partir de um clone limpo do zero):

1) Toque dos botoes da tela de reproducao se sobrepondo (clicar em Play
   as vezes ativava Anterior/Proxima; clicar em Repetir Todas as vezes
   ativava Repetir Uma):
   causa raiz - TODOS os botoes (incluindo o Play/Pause da classe base)
   usavam o drawable bg_vidcontrol como background com wrapContent. Esse
   drawable mede ~230dp de LARGURA (345x140px em hdpi - um fundo
   retangular largo, nao um icone quadrado), entao cada botao "inflava"
   pra esse tamanho gigante e as areas de toque ficavam se sobrepondo
   por dezenas de dp. Corrigido: todos os 6 botoes (Play/Pause, Anterior,
   Proxima, Repetir Todas, Repetir Uma, Editar Capa) agora tem tamanho
   FIXO e igual (48dp), fundo trocado por um ripple sem tamanho proprio
   (selectableItemBackgroundBorderless), e ScaleType.CENTER_INSIDE (em
   vez de CENTER) pra nenhum icone maior que o novo tamanho fixo ficar
   cortado. O piso da formula de espacamento entre Anterior/Play/Proxima
   tambem foi corrigido pra garantir zero sobreposicao possivel.

2) Botao de editar capa (lapis) movido mais pra cima e mais pro canto
   direito - encostado quase na quina superior direita da tela.

3) Crash ao clicar no editor (2a ocorrencia, CursorIndexOutOfBoundsException
   em getMetadataOrientation): mesma raiz do crash anterior (Uri de
   FileProvider sem colunas do MediaStore) - agora em outro metodo do
   ImageLoader.java, que ja tinha um try/catch pensado pra cair no
   fallback de EXIF quando a consulta falha, mas nao cobria esse tipo
   especifico de excecao. Corrigido.

4) Botoes de repetir sumindo da notificacao expandida DEPOIS da migracao
   pra MediaSessionCompat (script anterior): a migracao para
   MediaSessionCompat/PlaybackStateCompat/androidx.media foi uma
   tentativa de corrigir isso baseada numa teoria sobre o Android 13+
   que NAO se confirmou na pratica - no aparelho de teste (Samsung One
   UI 6.1, Android 14), os 5 botoes ja apareciam certinho com a
   MediaSession framework pura ANTES dessa migracao, e sumiram DEPOIS
   dela. Revertido de volta pra MediaSession/PlaybackState/
   Notification.MediaStyle framework (o que comprovadamente funciona
   nesse aparelho). Dependencia androidx.media:media removida do
   build.gradle.kts (nao e mais usada).

Rode este script de dentro de ~/Galeria3D (raiz do repo RECEM-CLONADO).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

FILES = {
    "app/src/main/java/com/android/gallery3d/app/MovieControllerOverlay.java": "MovieControllerOverlay.java",
    "app/src/main/java/com/android/gallery3d/app/MusicPlaybackService.java": "MusicPlaybackService.java",
    "app/src/main/java/com/android/gallery3d/filtershow/cache/ImageLoader.java": "ImageLoader.java",
    "app/build.gradle.kts": "build.gradle.kts",
}

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    path = "app/src/main/java/com/android/gallery3d/app/MovieControllerOverlay.java"
    if not os.path.isfile(path):
        return False
    with open(path, "r", encoding="utf-8") as f:
        return "BUTTON_SIZE_DP" in f.read()


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Correcao ja aplicada anteriormente (MovieControllerOverlay.java ja tem")
        print("BUTTON_SIZE_DP) - nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Correcao aplicada com sucesso.")
    print()
    print("O que foi feito:")
    print("- MovieControllerOverlay.java: todos os botoes com tamanho fixo")
    print("  (48dp) e fundo em ripple - fim da sobreposicao de toque; lapis")
    print("  movido pra quina superior direita")
    print("- ImageLoader.java: mais um ponto de crash do editor corrigido")
    print("  (getMetadataOrientation)")
    print("- MusicPlaybackService.java: REVERTIDO para MediaSession/")
    print("  PlaybackState framework (a migracao pra MediaSessionCompat do")
    print("  script anterior piorou a notificacao neste aparelho - voltou")
    print("  ao que funcionava)")
    print("- build.gradle.kts: dependencia androidx.media removida (nao")
    print("  usada mais)")
    print()
    print("Proximo passo: rode ./gradlew assembleDebug e teste:")
    print("1. Toque em Anterior/Play/Proxima e Repetir Todas/Repetir Uma")
    print("   (cada um deve responder so ao proprio toque agora)")
    print("2. Posicao do lapis (quina superior direita)")
    print("3. Editor de capa (nao deve mais crashar)")
    print("4. Notificacao expandida (os 5 botoes devem estar de volta)")


if __name__ == "__main__":
    main()
